const input = $input.first().json || {};
const documentId = String(input.documentId || '');
const workspaceId = String(input.workspaceId || '');

function httpStatus(res) {
  return res && res.statusCode !== undefined ? res.statusCode : res && res.status;
}

try {
  if (!documentId) {
    return [{ json: { success: false, error: 'documentId is required' } }];
  }

  const res = await $http.request({
    method: 'POST',
    url: `${$env.QDRANT_URL}/collections/careeros_pdf_chunks/points/delete`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      filter: {
        must: [{ key: 'document_id', match: { value: documentId } }],
      },
    },
  });
  if (httpStatus(res) >= 400) {
    return [
      {
        json: {
          success: false,
          error: `Qdrant delete returned status ${httpStatus(res)}: ${JSON.stringify(res.body || {})}`,
        },
      },
    ];
  }
  return [{ json: { success: true } }];
} catch (e) {
  return [{ json: { success: false, error: e && e.message ? String(e.message) : 'Unknown error' } }];
}
